#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STACK 64

static void error(void) {
    puts("ERROR");
    exit(0);
}

int main(int argc, char *argv[]) {
    long stack[MAX_STACK];
    int top = 0;
    if (argc < 2) error();
    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        char *endptr;
        long val = strtol(tok, &endptr, 10);
        if (*endptr == '\0') {
            if (top >= MAX_STACK) error();
            stack[top++] = val;
            continue;
        }
        if (strlen(tok) == 1) {
            char op = tok[0];
            if (op == '+' || op == '-' || op == '*' || op == '/') {
                if (top < 2) error();
                long right = stack[--top];
                long left = stack[--top];
                long res;
                switch (op) {
                    case '+': res = left + right; break;
                    case '-': res = left - right; break;
                    case '*': res = left * right; break;
                    case '/':
                        if (right == 0) error();
                        res = left / right; break;
                    default: error();
                }
                if (top >= MAX_STACK) error();
                stack[top++] = res;
                continue;
            }
        }
        error();
    }
    if (top != 1) error();
    printf("%ld\n", stack[0]);
    return 0;
}
